def transform(grid):
    h, w = len(grid), len(grid[0])
    wall = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    out = [[0] * w for _ in range(h)]

    if wall is not None:
        out[wall] = [2] * w

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 4:
                continue
            # Each 4 falls one cell.
            if r + 1 < h and r + 1 != wall:
                out[r + 1][c] = 4

            # The 4 two rows above the barrier creates expanding diagonal rays.
            if wall is not None and r == wall - 2:
                d = 1
                while r - d + 1 >= 0:
                    rr = r - d + 1
                    for cc in (c - d, c + d):
                        if 0 <= cc < w:
                            out[rr][cc] = 4
                    d += 1

    return out
